#!/usr/bin/env python3"""Fix collapsed line 743 in prompts.py - byte-level replacement."""from pathlib import Pathp = Path("bin/agent/prompts.py")raw = p.read_bytes()start = raw.find(b"def _serialize_element")end = raw.find(b"def _read_tree(path: Path)")if start == -1 or end == -1:    print(f"ERROR: markers not found (start={start}, end={end})")    raise SystemExit(1)print(f"Replacing bytes {start}..{end} ({end - start} bytes)")replacement = b'def _serialize_element(elem: ET.Element, indent: str = "") -> str:\n    """Serialize an Element to XML string with CDATA for value elements."""\n    parts: list[str] = []\n    tag = elem.tag\n    attrs = ""\n    for k, v in elem.attrib.items():\n        attrs += f\' {k}="{v}"\'\n    children = list(elem)\n    has_children = len(children) > 0\n    if tag == "value" and elem.text:\n        parts.append(f"{indent}<{tag}{attrs}><![CDATA[{elem.text}]]></{tag}>")\n        return "".join(parts)\n    if not has_children and (elem.text is None or not elem.text.strip()):\n        parts.append(f"{indent}<{tag}{attrs} />")\n    elif not has_children:\n        parts.append(f"{indent}<{tag}{attrs}>{elem.text or \'\'}</{tag}>")\n    else:\n        parts.append(f"{indent}<{tag}{attrs}>")\n        for child in children:\n            parts.append("\\n")\n            parts.append(_serialize_element(child, indent + "  "))\n        parts.append(f"\\n{indent}</{tag}>")\n    return "".join(parts)\n\n\ndef _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:\n    """Write the prompts XML tree to target using CDATA for value elements."""\n    root = tree.getroot()\n    xml_str = \'<?xml version="1.0" encoding="UTF-8"?>\\n\'\n    xml_str += _serialize_element(root)\n    xml_str += "\\n"\n    target.write_text(xml_str, encoding="utf-8")\n\n\n'new = raw[:start] + replacement + raw[end:]p.write_bytes(new)print(f"SUCCESS: wrote {len(new)} bytes (was {len(raw)})")